<?php $scans=$service->scans();$findings=$service->findings();$scanSchedules=array();if($workerService)foreach($workerService->tasks() as $task)if($task['worker_id']==='security_center.scheduled_scan')$scanSchedules[]=$task;?>
<form method="post"><input type="hidden" name="sc_page" value="scanner"><input type="hidden" name="action" value="settings"><input type="hidden" name="setting_scope" value="scanner"><?php echo $admin->getFTAN();?><section><h3>Scanner-Einstellungen</h3><div class="sec-options"><?php sec_switch($settings,'scanner_enabled','Codescanner aktivieren','Prüft PHP-Code portionsweise.');sec_switch($settings,'integrity_enabled','Dateiüberwachung aktivieren','Erkennt neue, geänderte und gelöschte Dateien.');?></div><div class="sec-form-grid"><label>Dateien je Scanlauf<input type="number" name="scanner_files_per_run" min="10" max="1000" value="<?php echo (int)$settings['scanner_files_per_run'];?>"></label><label>Scanintervall<input type="number" name="scanner_interval_minutes" min="1" max="1440" value="<?php echo (int)$settings['scanner_interval_minutes'];?>"><small>Minuten</small></label><label>Dateien je Integritätslauf<input type="number" name="integrity_files_per_run" min="10" max="2000" value="<?php echo (int)$settings['integrity_files_per_run'];?>"></label><label>Integritätsintervall<input type="number" name="integrity_interval_minutes" min="1" max="1440" value="<?php echo (int)$settings['integrity_interval_minutes'];?>"><small>Minuten</small></label><label class="sec-span">Überwachte Pfade<textarea name="integrity_paths" rows="3"><?php echo sec_h($settings['integrity_paths']);?></textarea></label></div><button>Scanner-Einstellungen speichern</button></section></form>
<section><h3>Einmalige Scanaufträge</h3><form method="post"><input type="hidden" name="sc_page" value="scanner"><input type="hidden" name="action" value="scan"><?php echo $admin->getFTAN();?><button>Neuen Scan einplanen</button></form><div class="sec-scroll"><table><thead><tr><th>Scan</th><th>Status</th><th>Dateien</th><th>Funde</th><th>Beginn</th><th></th></tr></thead><tbody><?php foreach($scans as $scan){?><tr><td><code><?php echo sec_h($scan['scan_id']);?></code></td><td><?php echo sec_h($scan['status']);?></td><td><?php echo (int)$scan['files_scanned'];?></td><td><?php echo (int)$scan['findings_count'];?></td><td><?php echo sec_h(sec_time($scan['started_at']?:$scan['created_at']));?></td><td><?php if($scan['status']==='queued'){?><form method="post" data-confirm="Soll dieser geplante Scan gelöscht werden?"><input type="hidden" name="sc_page" value="scanner"><input type="hidden" name="action" value="scan_delete"><input type="hidden" name="id" value="<?php echo (int)$scan['id'];?>"><?php echo $admin->getFTAN();?><button class="sec-danger">Löschen</button></form><?php }?></td></tr><?php }?></tbody></table></div></section>
<section><h3>Regelmäßige und terminierte Scans</h3><?php if(!$workerService){?><p>Für Scan-Zeitpläne muss der Worker installiert sein.</p><?php }else{?><form method="post" class="sec-schedule-form"><input type="hidden" name="sc_page" value="scanner"><input type="hidden" name="action" value="schedule_save"><?php echo $admin->getFTAN();?><label>Name<input name="name" value="Regelmäßiger Sicherheits-Scan"></label><div class="sec-choice"><label><input type="radio" name="schedule_mode" value="rate" checked> X-mal pro Zeitraum</label><label><input type="radio" name="schedule_mode" value="calendar"> Fester Kalendertermin</label></div><div class="sec-schedule-grid" data-schedule-mode="rate"><label>Anzahl<input type="number" name="schedule_count" min="1" max="12" value="1"></label><label>Zeitraum<select name="schedule_period"><option value="hour">Stunde</option><option value="day" selected>Tag</option><option value="week">Woche</option><option value="month">Monat</option><option value="year">Jahr</option></select></label><label>Startzeit<input type="time" name="schedule_time" value="03:00"></label></div><div class="sec-schedule-grid" data-schedule-mode="calendar" hidden><label>Rhythmus<select name="calendar_period" disabled><option value="once">Einmalig</option><option value="hour">Stündlich</option><option value="day">Täglich</option><option value="week">Wöchentlich</option><option value="month">Monatlich</option><option value="year">Jährlich</option></select></label><label data-once>Zeitpunkt<input type="datetime-local" name="run_at" disabled></label><label data-calendar-time>Uhrzeit<input type="time" name="schedule_time" value="03:00" disabled></label><label data-weekday>Wochentag<select name="schedule_weekday" disabled><option value="1">Montag</option><option value="2">Dienstag</option><option value="3">Mittwoch</option><option value="4">Donnerstag</option><option value="5">Freitag</option><option value="6">Samstag</option><option value="0">Sonntag</option></select></label><label data-monthday>Tag<input type="number" name="schedule_monthday" min="1" max="28" value="1" disabled></label><label data-month>Monat<select name="schedule_month" disabled><?php foreach(array('Januar','Februar','März','April','Mai','Juni','Juli','August','September','Oktober','November','Dezember') as $i=>$month)echo '<option value="'.($i+1).'">'.$month.'</option>';?></select></label></div><button>Zeitplan hinzufügen</button></form><div class="sec-scroll"><table><thead><tr><th>Name</th><th>Cron-Schema</th><th>Nächster Lauf</th><th>Status</th><th>Aktiv</th><th></th></tr></thead><tbody><?php foreach($scanSchedules as $schedule){?><tr><td><?php echo sec_h($schedule['name']);?></td><td><code><?php echo sec_h($schedule['cron_expression']);?></code></td><td><?php echo sec_h($schedule['next_run_display']?:'–');?></td><td><?php echo sec_h($schedule['last_status']?:'Bereit');?></td><td><form method="post"><input type="hidden" name="sc_page" value="scanner"><input type="hidden" name="action" value="schedule_toggle"><input type="hidden" name="schedule_id" value="<?php echo (int)$schedule['id'];?>"><input type="hidden" name="active" value="<?php echo $schedule['active']?'0':'1';?>"><?php echo $admin->getFTAN();?><label class="sec-slider"><input type="checkbox"<?php echo $schedule['active']?' checked':'';?> data-auto-submit><i></i></label></form></td><td><form method="post" data-confirm="Soll dieser Scan-Zeitplan gelöscht werden?"><input type="hidden" name="sc_page" value="scanner"><input type="hidden" name="action" value="schedule_delete"><input type="hidden" name="schedule_id" value="<?php echo (int)$schedule['id'];?>"><?php echo $admin->getFTAN();?><button class="sec-danger">Löschen</button></form></td></tr><?php }?></tbody></table></div><?php }?></section>
<section><h3>Offene Funde</h3><div class="sec-scroll"><table><thead><tr><th>Priorität</th><th>Datei</th><th>Regel</th><th>Aktion</th></tr></thead><tbody><?php foreach($findings as $finding){?><tr data-finding-row="<?php echo (int)$finding['id'];?>"><td><span class="sec-badge <?php echo sec_h($finding['severity']);?>"><?php echo sec_h($finding['severity']);?></span></td><td><strong><?php echo sec_h($finding['file_path']);?></strong><br><small><?php echo sec_h($finding['message']);?></small></td><td><?php echo sec_h($finding['rule_id']);?></td><td><div class="sec-finding-actions"><form method="post" data-preview-finding="<?php echo (int)$finding['id'];?>"><input type="hidden" name="sc_page" value="scanner"><input type="hidden" name="action" value="finding_preview"><input type="hidden" name="id" value="<?php echo (int)$finding['id'];?>"><?php echo $admin->getFTAN();?><button type="submit">Anzeigen</button></form><form method="post"><input type="hidden" name="sc_page" value="scanner"><input type="hidden" name="action" value="finding"><input type="hidden" name="id" value="<?php echo (int)$finding['id'];?>"><?php echo $admin->getFTAN();?><button name="status" value="resolved">Erledigt</button><button name="status" value="ignored">Ignorieren</button></form></div></td></tr><?php if($previewFinding&&$previewFinding['id']===(int)$finding['id']){?><tr data-finding-preview="<?php echo (int)$finding['id'];?>"><td colspan="4"><div class="sec-source-preview"><header><div><strong><?php echo sec_h($previewFinding['file_path']);?></strong><small>Fundzeile <?php echo (int)$previewFinding['line'];?> · <?php echo sec_h($previewFinding['rule_id']);?></small></div><button type="button" class="sec-secondary" data-close-preview>Schließen</button></header><div class="sec-source-scroll" data-source-scroll><?php echo WbceSecurityCenterCodePreview::render($previewFinding['content'],$previewFinding['line']);?></div></div></td></tr><?php }}?></tbody></table></div></section>
